import{_ as t}from"./chunks/lineup-card-voll.CF-ULOmt.js";import{_ as n,o as r,c as i,a3 as a}from"./chunks/framework.B9qR_F1m.js";const p=JSON.parse('{"title":"Lineup Card","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/lineup-card.md","filePath":"bereiche/lineup-card.md"}'),s={name:"bereiche/lineup-card.md"};function d(o,e,l,u,g,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="lineup-card" tabindex="-1">Lineup Card <a class="header-anchor" href="#lineup-card" aria-label="Permalink to &quot;Lineup Card&quot;">​</a></h1><p>Die Lineup Card ist die <strong>Hauptseite eines Flights im Cockpit</strong>. Shardwing füllt sie fast vollständig aus der Mission – du ergänzt nur, was die Mission nicht wissen kann.</p><p><img src="'+t+'" alt="Lineup Card mit Vorschau aller Kneeboard-Seiten eines Flights" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Platz schaffen</p><p>Mit <kbd>⌘⇧↵</kbd> / <kbd>Strg+Shift+Enter</kbd> blendest du die Karte aus und siehst alle Seiten nebeneinander.</p></div><h2 id="was-du-eintragst" tabindex="-1">Was du einträgst <a class="header-anchor" href="#was-du-eintragst" aria-label="Permalink to &quot;Was du einträgst&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feld</th><th>Wofür</th></tr></thead><tbody><tr><td><strong>Mission-Nr.</strong></td><td>Kopfzeile jeder Seite, z. B. „FS2439“</td></tr><tr><td><strong>Joker / Bingo</strong> (lbs)</td><td>Kraftstoff-Grenzen – fehlen sie, meldet die Übersicht es</td></tr><tr><td><strong>Hinweise</strong></td><td>Freitext, wird nur gedruckt, wenn ausgefüllt</td></tr><tr><td><strong>Kartenseiten und 9-Line</strong></td><td>welche Karten mitkommen und ob leere 9-Lines dabei sind, siehe unten</td></tr></tbody></table><p>Alles andere kommt aus der Mission und den anderen Bereichen.</p><h2 id="die-seiten-eines-flights" tabindex="-1">Die Seiten eines Flights <a class="header-anchor" href="#die-seiten-eines-flights" aria-label="Permalink to &quot;Die Seiten eines Flights&quot;">​</a></h2><p><strong>1 · Lineup Card</strong> – Zeiten (Start, T/O, Push, TOT, Land), alle Flugzeuge mit Pilot, Tail, Laser-Code, Joker/Bingo, Bullseye, Diverts mit Frequenz, TACAN und Bahn, die Beladung jedes Jets und deine Hinweise.</p><p><strong>2 · Comm Card</strong> – genau eine Seite: was im Jet auf COMM1 und COMM2 liegt (aus der Cartridge, sonst aus der Mission). Jeder Kanal, der zu einem Netz im <a href="./kneeboards#comm-plan">Comm Plan</a> passt, bekommt dessen Namen und Farbe. Darunter Navigation: TACAN, Divert-Frequenzen.</p><p><strong>3 · Routenkarte</strong> und weitere Kartenseiten – siehe unten.</p><p><strong>4 · Attack Card</strong> – eine Seite pro geplantem <a href="./angriff">Angriff</a>.</p><p><strong>5 · 9-Line</strong> – auf Wunsch, nach den Kartenseiten. Siehe unten.</p><p>Die Seiten richten sich nach der <strong>Quelle</strong> oben (Missionsroute oder Cartridge) – dieselbe wie im Reiter Route.</p><h2 id="kartenseiten" tabindex="-1">Kartenseiten <a class="header-anchor" href="#kartenseiten" aria-label="Permalink to &quot;Kartenseiten&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Art</th><th>Was</th></tr></thead><tbody><tr><td><strong>Routenkarte</strong></td><td>Die ganze Route auf einer Seite. An oder aus.</td></tr><tr><td><strong>+ Detailkarte</strong></td><td>Nahansicht um einen Steerpoint, z. B. IP und Ziel – mit Radius in NM.</td></tr><tr><td><strong>+ Ausschnitt</strong></td><td>Frei gewählter Ausschnitt: auf der Karte aufziehen, drehen (auch <strong>Kurs nach oben</strong>), eigene Ebenen und Koordinatengitter. <strong>Bearbeiten</strong> öffnet ihn groß.</td></tr><tr><td><strong>+ 9-Line</strong></td><td>Eine leere Seite für einen CAS-Brief zum Mitschreiben im Cockpit: JTAC, Frequenz, Game Plan, die neun Zeilen mit kurzer Erklärung, Remarks/Restrictions, TOT/TTT, Readback. Mehrmals drücken gibt mehrere Seiten, × nimmt eine wieder weg.</td></tr></tbody></table><p><strong>ME-Zeichnungen</strong> schaltet die Zeichnungen aus dem Mission Editor auf allen Karten an oder aus. Die Karten zeigen nur, was dieser Flight wissen darf – Threats, Grafiken seiner Koalition.</p><h2 id="ausgeben" tabindex="-1">Ausgeben <a class="header-anchor" href="#ausgeben" aria-label="Permalink to &quot;Ausgeben&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knopf</th><th>Ergebnis</th></tr></thead><tbody><tr><td><strong>In .miz einbetten…</strong></td><td>Die Seiten kommen ins Kneeboard des Flugzeugtyps und werden beim Speichern in die Mission geschrieben.</td></tr><tr><td><strong>PNG</strong></td><td>Einzelne Bilder, z. B. für OpenKneeboard</td></tr><tr><td><strong>PDF</strong></td><td>Alle Seiten in einem PDF</td></tr><tr><td><strong>Drucken</strong></td><td>Direkt drucken</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Kneeboards gelten pro Flugzeugtyp</p><p>DCS ordnet eingebettete Kneeboard-Seiten dem <strong>Typ</strong> zu, nicht dem Flight. Fliegen zwei F-16-Flights, sehen beide die Lineup Cards beider Flights. Das ist meist gewollt (man findet seine Card über den Index). Hat ein Flight aber geheime Threats, verteile seine Unterlagen besser per <a href="/dcs/speichern#export">Export</a>.</p></div><h2 id="index-und-reihenfolge" tabindex="-1">Index und Reihenfolge <a class="header-anchor" href="#index-und-reihenfolge" aria-label="Permalink to &quot;Index und Reihenfolge&quot;">​</a></h2><p>Im Bereich <a href="./kneeboards">Kneeboards</a> gibt es die Vorlage <strong>Index</strong>: eine erste Seite mit allen Flights, ihrer Farbe, Muster, Auftrag und den <strong>Seitenzahlen</strong> ihrer Lineup Cards. So findet jeder Pilot mit <kbd>K</kbd> und Blättern schnell seine Seite.</p>',22)])])}const m=n(s,[["render",d]]);export{p as __pageData,m as default};
